from threading import Semaphore

class FizzBuzz:
    def __init__(self, n: int):
        self.n = n
        self.i = 1
        self.sNum = Semaphore(1)
        self.sFizz = Semaphore(0)
        self.sBuzz = Semaphore(0)
        self.sFB = Semaphore(0)

    def fizz(self, printFizz: 'Callable[[], None]') -> None:
        while self.i <= self.n:
            self.sFizz.acquire()
            if self.i % 3 == 0 and self.i % 5 != 0:
                printFizz()
                self.i += 1
                self._release()
            else:
                self.sFizz.release()

    def buzz(self, printBuzz: 'Callable[[], None]') -> None:
        while self.i <= self.n:
            self.sBuzz.acquire()
            if self.i % 5 == 0 and self.i % 3 != 0:
                printBuzz()
                self.i += 1
                self._release()
            else:
                self.sBuzz.release()

    def fizzbuzz(self, printFizzBuzz: 'Callable[[], None]') -> None:
        while self.i <= self.n:
            self.sFB.acquire()
            if self.i % 15 == 0:
                printFizzBuzz()
                self.i += 1
                self._release()
            else:
                self.sFB.release()

    def number(self, printNumber: 'Callable[[int], None]') -> None:
        while self.i <= self.n:
            self.sNum.acquire()
            if self.i % 3 != 0 and self.i % 5 != 0:
                printNumber(self.i)
                self.i += 1
                self._release()
            else:
                self.sNum.release()

    def _release(self):
        i = self.i
        if i > self.n:
            return
        if i % 15 == 0:
            self.sFB.release()
        elif i % 3 == 0:
            self.sFizz.release()
        elif i % 5 == 0:
            self.sBuzz.release()
        else:
            self.sNum.release()

