import java.util.concurrent.Semaphore;
import java.util.function.IntConsumer;

class FizzBuzz {
    private int n;
    private int i = 1;
    private final Semaphore sNum = new Semaphore(1);
    private final Semaphore sFizz = new Semaphore(0);
    private final Semaphore sBuzz = new Semaphore(0);
    private final Semaphore sFB = new Semaphore(0);

    public FizzBuzz(int n) { this.n = n; }

    private void releaseNext() {
        if (i > n) return;
        if (i % 15 == 0) sFB.release();
        else if (i % 3 == 0) sFizz.release();
        else if (i % 5 == 0) sBuzz.release();
        else sNum.release();
    }

    public void fizz(Runnable printFizz) throws InterruptedException {
        while (i <= n) {
            sFizz.acquire();
            if (i % 3 == 0 && i % 5 != 0) { printFizz.run(); i++; releaseNext(); }
            else sFizz.release();
        }
    }

    public void buzz(Runnable printBuzz) throws InterruptedException {
        while (i <= n) {
            sBuzz.acquire();
            if (i % 5 == 0 && i % 3 != 0) { printBuzz.run(); i++; releaseNext(); }
            else sBuzz.release();
        }
    }

    public void fizzbuzz(Runnable printFizzBuzz) throws InterruptedException {
        while (i <= n) {
            sFB.acquire();
            if (i % 15 == 0) { printFizzBuzz.run(); i++; releaseNext(); }
            else sFB.release();
        }
    }

    public void number(IntConsumer printNumber) throws InterruptedException {
        while (i <= n) {
            sNum.acquire();
            if (i % 3 != 0 && i % 5 != 0) { printNumber.accept(i); i++; releaseNext(); }
            else sNum.release();
        }
    }
}

