#include <functional>
#include <condition_variable>
#include <mutex>
class FizzBuzz {
private:
    int n;
    int i = 1;
    std::mutex m;
    std::condition_variable cv;
    template <typename Pred, typename Print>
    void run(Pred pred, Print print) {
        std::unique_lock<std::mutex> lk(m);
        while (i <= n) {
            if (pred(i)) { print(); i++; cv.notify_all(); }
            else cv.wait(lk);
        }
    }
public:
    FizzBuzz(int n) : n(n) {}
    void fizz(std::function<void()> printFizz) {
        run([](int x){ return x % 3 == 0 && x % 5 != 0; }, printFizz);
    }
    void buzz(std::function<void()> printBuzz) {
        run([](int x){ return x % 5 == 0 && x % 3 != 0; }, printBuzz);
    }
    void fizzbuzz(std::function<void()> printFizzBuzz) {
        run([](int x){ return x % 15 == 0; }, printFizzBuzz);
    }
    void number(std::function<void(int)> printNumber) {
        run([](int x){ return x % 3 != 0 && x % 5 != 0; }, [printNumber, this]{ printNumber(i); });
    }
};

