class FizzBuzz {
    constructor(n) {
        this.n = n;
        this.i = 1;
        this.resolvers = [];
    }
    async _try(pred, act) {
        while (this.i <= this.n) {
            if (pred(this.i)) { act(this.i); this.i++; this._wake(); return; }
            await new Promise(res => this.resolvers.push(res));
        }
    }
    _wake() {
        const rs = this.resolvers;
        this.resolvers = [];
        rs.forEach(r => r());
    }
    fizz(printFizz) {
        return this._try(x => x % 3 === 0 && x % 5 !== 0, () => printFizz());
    }
    buzz(printBuzz) {
        return this._try(x => x % 5 === 0 && x % 3 !== 0, () => printBuzz());
    }
    fizzbuzz(printFizzBuzz) {
        return this._try(x => x % 15 === 0, () => printFizzBuzz());
    }
    number(printNumber) {
        return this._try(x => x % 3 !== 0 && x % 5 !== 0, x => printNumber(x));
    }
}
